/**
 * Implements the {@code :has(relative-selector-list)} structural pseudo-class. Each branch of the selector list is
 * evaluated independently against the candidate element acting as the anchor:
 * <ul>
 *   <li>a branch without a leading combinator, or starting with {@code >}, matches only within the anchor's
 *       descendants (with the {@link Root} pin enforcing direct-child semantics for {@code >});</li>
 *   <li>a branch starting with {@code +} checks only the anchor's immediately following element sibling;</li>
 *   <li>a branch starting with {@code ~} checks any following element sibling.</li>
 * </ul>
 * For sibling branches, the selector chain may continue below the matched sibling (e.g. {@code :has(~ p span)}),
 * so that sibling's descendants are searched when the chain requires it. Non-element nodes do not participate in
 * sibling relationships.
 */
static class Has extends StructuralEvaluator {
    static final SoftPool<NodeIterator<Node>> NodeIterPool =
        new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class));
    // the element here is just a placeholder so this can be final - gets set in restart()

    private final List<Branch> branches;

    public Has(Evaluator evaluator) {
        super(evaluator);
        branches = resolveBranches(evaluator);
    }

    @Override public boolean matches(Element root, Element element) {
        for (Branch branch : branches) {
            if (branch.axis == 0) {
                if (matchesDescendant(element, branch.eval)) return true;
            } else if (matchesSibling(element, branch)) {
                return true;
            }
        }
        return false;
    }

    // match within the anchor's subtree only (not the anchor itself)
    private boolean matchesDescendant(Element anchor, Evaluator eval) {
        NodeIterator<Node> it = NodeIterPool.borrow();
        it.restart(anchor);
        try {
            while (it.hasNext()) {
                Node node = it.next();
                if (node == anchor) continue; // don't match self, only descendants
                if (eval.matches(anchor, node)) return true;
            }
        } finally {
            NodeIterPool.release(it);
        }
        return false;
    }

    // match against following element siblings (+ : just the immediate one; ~ : any), and possibly below them
    private boolean matchesSibling(Element anchor, Branch branch) {
        NodeIterator<Node> it = branch.descends ? NodeIterPool.borrow() : null;
        try {
            int seen = 0;
            for (Element sib = anchor.nextElementSibling(); sib != null; sib = sib.nextElementSibling()) {
                if (branch.axis == '+' && seen > 0) break; // adjacent only
                seen++;

                if (branch.eval.matches(anchor, sib)) return true;

                if (branch.descends) { // the selector chain continues below the sibling
                    it.restart(sib);
                    while (it.hasNext()) {
                        Node node = it.next();
                        if (node == sib) continue;
                        if (branch.eval.matches(anchor, node)) return true;
                    }
                }
            }
        } finally {
            if (it != null) NodeIterPool.release(it);
        }
        return false;
    }

    @Override
    boolean evaluateMatch(Element root, Node node) {
        return false; // a leaf node cannot be a :has() anchor
    }

    private static final class Branch {
        final char axis; // 0 = descendant scoped, '+' = next sibling, '~' = later siblings
        final Evaluator eval;
        final boolean descends; // sibling axis, and the chain continues below the matched sibling

        Branch(char axis, Evaluator eval) {
            this.axis = axis;
            this.eval = eval;
            this.descends = axis != 0 && descendsBelowSibling(eval);
        }
    }

    /** Split the selector list into its independent branches (the top-level Or from the commas). */
    private static List<Branch> resolveBranches(Evaluator eval) {
        ArrayList<Evaluator> clauses = new ArrayList<>();
        collectOrClauses(eval, clauses);
        ArrayList<Branch> branches = new ArrayList<>(clauses.size());
        for (Evaluator clause : clauses) {
            branches.add(new Branch(leadingSiblingAxis(clause), clause));
        }
        return branches;
    }

    private static void collectOrClauses(Evaluator eval, List<Evaluator> clauses) {
        if (eval instanceof CombiningEvaluator.Or) {
            for (Evaluator clause : ((CombiningEvaluator.Or) eval).evaluators)
                collectOrClauses(clause, clauses);
        } else {
            clauses.add(eval);
        }
    }

    /**
     * Finds the leading relative combinator of a branch, if any. A leading {@code +} / {@code ~} is represented by
     * an ImmediatePreviousSibling / PreviousSibling whose left side pins the {@link Root} element (the anchor).
     * Nested :has(), :is(), and :not() scopes are opaque and not entered.
     */
    private static char leadingSiblingAxis(Evaluator eval) {
        if (eval instanceof StructuralEvaluator.ImmediatePreviousSibling
            && anchorsRoot(((StructuralEvaluator) eval).evaluator)) return '+';
        if (eval instanceof StructuralEvaluator.PreviousSibling
            && anchorsRoot(((StructuralEvaluator) eval).evaluator)) return '~';

        if (eval instanceof CombiningEvaluator) {
            for (Evaluator child : ((CombiningEvaluator) eval).evaluators) {
                char axis = leadingSiblingAxis(child);
                if (axis != 0) return axis;
            }
        } else if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
            for (Evaluator child : ((StructuralEvaluator.ImmediateParentRun) eval).evaluators) {
                char axis = leadingSiblingAxis(child);
                if (axis != 0) return axis;
            }
        } else if (eval instanceof StructuralEvaluator.Ancestor) {
            return leadingSiblingAxis(((StructuralEvaluator.Ancestor) eval).evaluator);
        }
        return 0;
    }

/** Whether the evaluator pins its left side to the implicit Root (i.e. the branch started with a combinator). */
private static boolean anchorsRoot(Evaluator eval) {
    if (eval instanceof StructuralEvaluator.Root) return true;
    if (eval instanceof CombiningEvaluator) {
        for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
            if (anchorsRoot(child)) return true;
    } else if (eval instanceof StructuralEvaluator.ImmediateParentRun) {
        for (Evaluator child : ((StructuralEvaluator.ImmediateParentRun) eval).evaluators)
            if (anchorsRoot(child)) return true;
    } else if (eval instanceof StructuralEvaluator) {
        return anchorsRoot(((StructuralEvaluator) eval).evaluator);
    }
    return false;
}

    /**
     * Whether a sibling-relative branch continues below the matched sibling. A descendant or child step is
     * represented by an Ancestor or ImmediateParentRun. Other structural evaluators (including sibling
     * combinators and nested :has/:is/:not) resolve themselves against the sibling element directly.
     */
    private static boolean descendsBelowSibling(Evaluator eval) {
        if (eval instanceof StructuralEvaluator.Ancestor
            || eval instanceof StructuralEvaluator.ImmediateParentRun) return true;
        if (eval instanceof CombiningEvaluator) {
            for (Evaluator child : ((CombiningEvaluator) eval).evaluators)
                if (descendsBelowSibling(child)) return true;
        }
