private static final class Branch {
    final char axis; // 0 = within anchor subtree (leading none or '>'), '+' = next sibling, '~' = later siblings
    final Evaluator eval;
    final boolean descends; // a sibling chain that continues below the matched sibling

    Branch(char axis, Evaluator eval, boolean descends) {
        this.axis = axis;
        this.eval = eval;
        this.descends = descends;
    }
}

/** Split the selector list into its independent branches (the top-level Or from the commas). */
private static List<Branch> resolveBranches(Evaluator eval) {
    ArrayList<Evaluator> clauses = new ArrayList<>();
    collectOrClauses(eval, clauses);
    ArrayList<Branch> branches = new ArrayList<>(clauses.size());
    for (Evaluator clause : clauses) {
        // walk the combinator chain from right to left: the last combinator reached is the branch's leading one
        char axis = 0;
        boolean descends = false;
        Evaluator cur = clause;
        char combinator;
        while ((combinator = rightmostCombinator(cur)) != 0) {
            axis = combinator == '+' || combinator == '~' ? combinator : 0;
            if (combinator == ' ' || combinator == '>') descends = true; // a down-step right of the leading sibling
            cur = leftSide(cur, combinator);
        }
        branches.add(new Branch(axis, clause, axis != 0 && descends));
    }
    return branches;
}

private static void collectOrClauses(Evaluator eval, List<Evaluator> clauses) {
    if (eval instanceof CombiningEvaluator.Or) {
        for (Evaluator clause : ((CombiningEvaluator.Or) eval).evaluators)
            collectOrClauses(clause, clauses);
    } else {
        clauses.add(eval);
    }
}

/**
 * The rightmost (last parsed) combinator of a linear selector chain. A chain combinator is held directly by an
 * And ({@code } descendant, {@code +} / {@code ~} sibling) or an ImmediateParentRun ({@code >}). Nested
 * :has(), :is(), and :not() scopes never appear on this spine and so are naturally opaque.
 * @return {@code ' '}, {@code '>'}, {@code '+'}, {@code '~'}, or {@code 0} if there is no combinator
 */
private static char rightmostCombinator(Evaluator eval) {
    if (eval instanceof StructuralEvaluator.ImmediateParentRun) return '>';
    if (eval instanceof CombiningEvaluator.And) {
        for (Evaluator child : ((CombiningEvaluator.And) eval).evaluators) {
            if (child instanceof StructuralEvaluator.ImmediatePreviousSibling) return '+';
            if (child instanceof StructuralEvaluator.PreviousSibling) return '~';
            if (child instanceof StructuralEvaluator.Ancestor) return ' ';
            if (child instanceof StructuralEvaluator.ImmediateParentRun) return '>';
        }
    }
    return 0;
}

/** The left-hand evaluator wrapped by the combinator reported by {@link #rightmostCombinator(Evaluator)}. */
private static Evaluator leftSide(Evaluator eval, char combinator) {
    if (eval instanceof StructuralEvaluator.ImmediateParentRun)
        return ((StructuralEvaluator.ImmediateParentRun) eval).evaluators.get(0);
    CombiningEvaluator.And and = (CombiningEvaluator.And) eval;
    for (Evaluator child : and.evaluators) {
        switch (combinator) {
            case '+':
                if (child instanceof StructuralEvaluator.ImmediatePreviousSibling)
                    return ((StructuralEvaluator) child).evaluator;
                break;
            case '~':
                if (child instanceof StructuralEvaluator.PreviousSibling)
                    return ((StructuralEvaluator) child).evaluator;
                break;
            case ' ':
                if (child instanceof StructuralEvaluator.Ancestor)
                    return ((StructuralEvaluator) child).evaluator;
                break;
            case '>':
                if (child instanceof StructuralEvaluator.ImmediateParentRun)
                    return ((StructuralEvaluator.ImmediateParentRun) child).evaluators.get(0);
                break;
        }
    }
    throw new IllegalStateException("Undeclared combinator " + combinator); // should not happen
}

