        p("last li none", d2.select("li#2:has(+ li)").size()); // 0
        // context scoped (not whole document)
        Document d3 = Jsoup.parse("<div id=a><p><img></p></div><div id=b><img></div>");
        p("context > img", d3.selectFirst("#a").select(":has(> img)").eachAttr("id")); // p only
        // mixed ordinary + has + nested
        p("nested combo", doc.select("div:has(p):has(+ div)").eachAttr("id")); // [d]? d has no p... e has p. d has +div e yes but no p. => none
        Document d4 = Jsoup.parse("<div id=x><p></p></div><div id=y></div>");
        p("x has p and +div", d4.select("div:has(p):has(+ div)").eachAttr("id")); // [x]
    }
}
