        Elements r2 = d3.select(":has(> img)");
        StringBuilder sb2=new StringBuilder();
        r2.forEach(e->sb2.append(e.tagName()).append('#').append(e.id()).append(' '));
        System.out.println("doc :has(> img) -> [" + sb2 + "] want [p, div#b]");
